insert into public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, category, country, vocation, religious_order, birthplace, bio, full_bio, mission, legacy, spirituality_summary, key_events, status, source_name, source_url, bio_source_url, source_metadata)
values
('santa-catarina-de-sena', 'Santa Catarina de Sena', 'Virgem e Doutora da Igreja', '29 de abril', 4, 29, '1347', '29 de abril de 1380', 'doctor', 'Itália', 'Leiga consagrada na família dominicana; Doutora da Igreja', null, 'Siena, Itália', 'Mística dominicana de Siena, Catarina uniu profunda contemplação de Cristo a intensa atividade apostólica. Sua vida foi marcada pelo amor à Igreja e pelo serviço em tempos de crise.', 'Catarina nasceu em Siena em 1347. Desde jovem dedicou-se a Cristo e cultivou uma vida interior intensa. Tornou-se conhecida por sua oração, caridade e atuação em favor da unidade e da renovação da Igreja. Morreu em Roma em 29 de abril de 1380 e foi proclamada Doutora da Igreja em 1970.', 'Servir à Igreja por meio da oração, da caridade e do apelo à unidade.', 'Sua vida contemplativa e apostólica permanece referência para a vida cristã.', 'Catarina testemunha que a contemplação de Cristo crucificado deve produzir caridade e compromisso com a Igreja.', '[]'::jsonb, 'active', 'Santa Sé', 'https://www.vatican.va/content/john-paul-ii/pt/homilies/1980/documents/hf_jp-ii_hom_19800429_centenario-caterina-siena.html', 'https://www.vatican.va/content/john-paul-ii/pt/homilies/1980/documents/hf_jp-ii_hom_19800429_centenario-caterina-siena.html', '{"century":14,"sources":[{"url":"https://www.vatican.va/content/john-paul-ii/pt/homilies/1980/documents/hf_jp-ii_hom_19800429_centenario-caterina-siena.html","year":"1980","title":"Homilia no VI centenário da morte de Santa Catarina de Sena","author":"João Paulo II — Santa Sé"}],"biography_full":{"missao":"Servir à Igreja por meio da oração, da caridade e do apelo à unidade.","origem":"Siena, Itália","chamado":"Leiga consagrada na família dominicana; Doutora da Igreja","heranca":"Sua vida contemplativa e apostólica permanece referência para a vida cristã.","testemunho":"Catarina testemunha que a contemplação de Cristo crucificado deve produzir caridade e compromisso com a Igreja."},"content_status":"partial","historical_context":"Itália do século XIV, marcada por conflitos políticos e desafios eclesiais.","spiritual_practice":{"prayer":"Santa Catarina de Sena, rogai por nós.","purpose":"Catarina testemunha que a contemplação de Cristo crucificado deve produzir caridade e compromisso com a Igreja.","live_today":"Traduzir a virtude cristã em um gesto concreto no cotidiano."}}'::jsonb),
('santa-teresa-de-jesus', 'Santa Teresa de Jesus', 'Teresa de Ávila; Doutora da Igreja', '15 de outubro', 10, 15, '28 de março de 1515', '4 de outubro de 1582', 'doctor', 'Espanha', 'Carmelita; reformadora; Doutora da Igreja', null, 'Ávila, Espanha', 'Carmelita, reformadora e Doutora da Igreja, Teresa de Jesus ensinou a oração como amizade com Deus. Sua vida contemplativa foi acompanhada por intensa atividade de fundação e serviço eclesial.', 'Teresa nasceu em Ávila, na Espanha. Entrou no Carmelo e, após uma profunda experiência de conversão e oração, iniciou a reforma da Ordem Carmelita. Escreveu obras centrais da espiritualidade cristã, como Livro da Vida e Castelo Interior. Foi proclamada Doutora da Igreja em 1970.', 'Reformar o Carmelo e ensinar a vida de oração como amizade com Deus.', 'Suas obras e fundações permanecem referência para a espiritualidade cristã.', 'Teresa ensina que a oração é relação de amizade com Aquele que sabemos que nos ama.', '[]'::jsonb, 'active', 'Santa Sé', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2011/documents/hf_ben-xvi_aud_20110202.html', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2011/documents/hf_ben-xvi_aud_20110202.html', '{"century":16,"sources":[{"url":"https://www.vatican.va/content/benedict-xvi/pt/audiences/2011/documents/hf_ben-xvi_aud_20110202.html","year":"2011","title":"Audiência geral — Santa Teresa de Ávila","author":"Bento XVI — Santa Sé"}],"biography_full":{"missao":"Reformar o Carmelo e ensinar a vida de oração como amizade com Deus.","origem":"Ávila, Espanha","chamado":"Carmelita; reformadora; Doutora da Igreja","heranca":"Suas obras e fundações permanecem referência para a espiritualidade cristã.","testemunho":"Teresa ensina que a oração é relação de amizade com Aquele que sabemos que nos ama."},"content_status":"partial","historical_context":"Espanha do século XVI e reforma católica da vida religiosa.","spiritual_practice":{"prayer":"Santa Teresa de Jesus, rogai por nós.","purpose":"Teresa ensina que a oração é relação de amizade com Aquele que sabemos que nos ama.","live_today":"Traduzir a virtude cristã em um gesto concreto no cotidiano."}}'::jsonb),
('santa-teresinha-do-menino-jesus', 'Santa Teresinha do Menino Jesus', 'Doutora da Igreja e Padroeira das Missões', '1 de outubro', 10, 1, '2 de janeiro de 1873', '30 de setembro de 1897', 'mystic', 'França', 'Carmelita; Doutora da Igreja', null, 'Alençon e Lisieux, França', 'Carmelita de Lisieux, Teresa viveu apenas 24 anos, mas sua doutrina espiritual iluminou a Igreja. Ensinou o caminho da confiança em Jesus e do amor vivido nas pequenas coisas.', 'Teresa nasceu em Alençon, na França, e ingressou no Carmelo de Lisieux ainda adolescente. Sua vida simples e escondida foi marcada pela confiança na misericórdia de Deus e pelo desejo de amar no coração da Igreja. Seus escritos foram reunidos em História de uma alma; João Paulo II proclamou-a Doutora da Igreja em 1997.', 'Rezar pelos missionários e viver o amor a Jesus nas pequenas ações cotidianas.', 'Doutora da Igreja e Padroeira das Missões; sua pequena via continua a inspirar cristãos.', 'A pequena via de Teresa ensina confiança filial, abandono em Deus e amor concreto nas pequenas coisas.', '[]'::jsonb, 'active', 'Santa Sé', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2011/documents/hf_ben-xvi_aud_20110406.html', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2011/documents/hf_ben-xvi_aud_20110406.html', '{"century":19,"sources":[{"url":"https://www.vatican.va/content/benedict-xvi/pt/audiences/2011/documents/hf_ben-xvi_aud_20110406.html","year":"2011","title":"Audiência geral — Santa Teresa de Lisieux","author":"Bento XVI — Santa Sé"}],"biography_full":{"missao":"Rezar pelos missionários e viver o amor a Jesus nas pequenas ações cotidianas.","origem":"Alençon e Lisieux, França","chamado":"Carmelita; Doutora da Igreja","heranca":"Doutora da Igreja e Padroeira das Missões; sua pequena via continua a inspirar cristãos.","testemunho":"A pequena via de Teresa ensina confiança filial, abandono em Deus e amor concreto nas pequenas coisas."},"content_status":"partial","historical_context":"França do final do século XIX e renovação da espiritualidade carmelita.","spiritual_practice":{"prayer":"Santa Teresinha do Menino Jesus, rogai por nós.","purpose":"A pequena via de Teresa ensina confiança filial, abandono em Deus e amor concreto nas pequenas coisas.","live_today":"Traduzir a virtude cristã em um gesto concreto no cotidiano."}}'::jsonb),
('santo-agostinho', 'Santo Agostinho de Hipona', 'Bispo e Doutor da Igreja', '28 de agosto', 8, 28, '13 de novembro de 354', '28 de agosto de 430', 'doctor', 'Argélia', 'Bispo; teólogo; Doutor da Igreja', null, 'Tagaste, Norte da África', 'Bispo de Hipona e Doutor da Igreja, Agostinho percorreu uma longa busca intelectual e espiritual até sua conversão. Suas Confissões e escritos teológicos marcaram profundamente a tradição cristã.', 'Agostinho nasceu em Tagaste, no Norte da África. Depois de uma juventude marcada por inquietações intelectuais e morais, aproximou-se da fé cristã, foi batizado por Ambrósio de Milão e tornou-se bispo de Hipona. Sua obra une reflexão filosófica, leitura das Escrituras, vida pastoral e busca da verdade em Deus.', 'Servir à Igreja como bispo, pastor e mestre da fé.', 'Seus escritos permanecem referência para a teologia, a filosofia e a espiritualidade cristãs.', 'A vida de Agostinho convida a reconhecer a inquietação do coração e a orientar a inteligência e a vontade para Deus.', '[]'::jsonb, 'active', 'Santa Sé', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2008/documents/hf_ben-xvi_aud_20080109.html', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2008/documents/hf_ben-xvi_aud_20080109.html', '{"century":4,"sources":[{"url":"https://www.vatican.va/content/benedict-xvi/pt/audiences/2008/documents/hf_ben-xvi_aud_20080109.html","year":"2008","title":"Audiência geral — Santo Agostinho de Hipona","author":"Bento XVI — Santa Sé"}],"biography_full":{"missao":"Servir à Igreja como bispo, pastor e mestre da fé.","origem":"Tagaste, Norte da África","chamado":"Bispo; teólogo; Doutor da Igreja","heranca":"Seus escritos permanecem referência para a teologia, a filosofia e a espiritualidade cristãs.","testemunho":"A vida de Agostinho convida a reconhecer a inquietação do coração e a orientar a inteligência e a vontade para Deus."},"content_status":"partial","historical_context":"Cristianismo norte-africano na Antiguidade tardia.","spiritual_practice":{"prayer":"Santo Agostinho de Hipona, rogai por nós.","purpose":"A vida de Agostinho convida a reconhecer a inquietação do coração e a orientar a inteligência e a vontade para Deus.","live_today":"Traduzir a virtude cristã em um gesto concreto no cotidiano."}}'::jsonb),
('sao-bento-de-nursia', 'São Bento de Núrsia', 'Fundador do monaquismo ocidental', '11 de julho', 7, 11, 'c. 480', 'c. 547', 'founder', 'Itália', 'Abade; fundador monástico', null, 'Núrsia, Itália', 'São Bento é reconhecido como fundador do monaquismo ocidental. Sua vida e sua Regra influenciaram profundamente a oração, a vida comunitária e a cultura cristã da Europa.', 'Bento nasceu em Núrsia e, ainda jovem, retirou-se para a solidão de Subiaco. Depois reuniu discípulos e estabeleceu uma forma de vida monástica marcada pela oração, pelo trabalho, pela obediência e pela estabilidade comunitária. A Regra de São Bento tornou-se uma das grandes referências da tradição monástica ocidental.', 'Formar comunidades monásticas centradas na oração, no trabalho e na escuta da Palavra.', 'A Regra beneditina influenciou a vida monástica e a cultura cristã ocidental.', 'A espiritualidade beneditina ensina a buscar Deus na oração, na vida comum e no trabalho cotidiano.', '[]'::jsonb, 'active', 'Santa Sé', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2008/documents/hf_ben-xvi_aud_20080409.html', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2008/documents/hf_ben-xvi_aud_20080409.html', '{"century":6,"sources":[{"url":"https://www.vatican.va/content/benedict-xvi/pt/audiences/2008/documents/hf_ben-xvi_aud_20080409.html","year":"2008","title":"Audiência geral — São Bento de Núrsia","author":"Bento XVI — Santa Sé"}],"biography_full":{"missao":"Formar comunidades monásticas centradas na oração, no trabalho e na escuta da Palavra.","origem":"Núrsia, Itália","chamado":"Abade; fundador monástico","heranca":"A Regra beneditina influenciou a vida monástica e a cultura cristã ocidental.","testemunho":"A espiritualidade beneditina ensina a buscar Deus na oração, na vida comum e no trabalho cotidiano."},"content_status":"partial","historical_context":"Transição da Antiguidade tardia para a Europa medieval.","spiritual_practice":{"prayer":"São Bento de Núrsia, rogai por nós.","purpose":"A espiritualidade beneditina ensina a buscar Deus na oração, na vida comum e no trabalho cotidiano.","live_today":"Traduzir a virtude cristã em um gesto concreto no cotidiano."}}'::jsonb),
('sao-francisco-de-assis', 'São Francisco de Assis', 'Fundador dos Frades Menores', '4 de outubro', 10, 4, '1181 ou 1182', '3 de outubro de 1226', 'founder', 'Itália', 'Fundador; diácono', null, 'Assis, Itália', 'Francisco de Assis abandonou uma vida confortável para seguir Cristo na pobreza evangélica. Fundador dos Frades Menores, tornou-se testemunha de fraternidade, paz e cuidado com a criação.', 'Nascido em Assis, Francisco viveu uma conversão que o levou a abraçar a pobreza e a fraternidade. Reuniu companheiros em uma forma de vida centrada no Evangelho e na confiança em Deus. Sua espiritualidade contempla todas as criaturas como irmãs e irmãos, sem retirar Cristo do centro.', 'Viver e anunciar o Evangelho em fraternidade, simplicidade e paz.', 'Sua vida inspirou uma família espiritual presente em todo o mundo e um testemunho cristão de cuidado com a criação.', 'Francisco convida a seguir Cristo pobre e a reconhecer a fraternidade que alcança toda a criação.', '[]'::jsonb, 'active', 'Santa Sé', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2010/documents/hf_ben-xvi_aud_20100127.html', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2010/documents/hf_ben-xvi_aud_20100127.html', '{"century":13,"sources":[{"url":"https://www.vatican.va/content/benedict-xvi/pt/audiences/2010/documents/hf_ben-xvi_aud_20100127.html","year":"2010","title":"Audiência geral — São Francisco de Assis","author":"Bento XVI — Santa Sé"}],"biography_full":{"missao":"Viver e anunciar o Evangelho em fraternidade, simplicidade e paz.","origem":"Assis, Itália","chamado":"Fundador; diácono","heranca":"Sua vida inspirou uma família espiritual presente em todo o mundo e um testemunho cristão de cuidado com a criação.","testemunho":"Francisco convida a seguir Cristo pobre e a reconhecer a fraternidade que alcança toda a criação."},"content_status":"partial","historical_context":"Itália comunal e movimentos de renovação evangélica do século XIII.","spiritual_practice":{"prayer":"São Francisco de Assis, rogai por nós.","purpose":"Francisco convida a seguir Cristo pobre e a reconhecer a fraternidade que alcança toda a criação.","live_today":"Traduzir a virtude cristã em um gesto concreto no cotidiano."}}'::jsonb),
('sao-joao-paulo-ii', 'São João Paulo II', 'Papa e sucessor de Pedro', '22 de outubro', 10, 22, '18 de maio de 1920', '2 de abril de 2005', 'pope', 'Polônia', 'Sacerdote; bispo; Papa', null, 'Wadowice, Polônia', 'Karol Wojtyła nasceu em Wadowice, na Polônia. Foi sacerdote, bispo de Cracóvia e Papa de 1978 a 2005. Seu ministério destacou a dignidade humana, a esperança e a centralidade de Cristo.', 'João Paulo II nasceu em 1920 em Wadowice. Estudou, trabalhou durante a ocupação nazista e entrou no seminário clandestino de Cracóvia. Foi ordenado sacerdote em 1946, tornou-se arcebispo de Cracóvia e foi eleito Papa em 16 de outubro de 1978. Seu pontificado foi marcado por numerosas viagens apostólicas e ensinamentos sobre Cristo, a pessoa humana e a família. Foi canonizado em 2014.', 'Conduzir a Igreja como sucessor de Pedro e anunciar Cristo em todos os continentes.', 'Seu magistério e testemunho pastoral continuam a influenciar a Igreja contemporânea.', 'João Paulo II convidou repetidamente a abrir as portas a Cristo e a viver a esperança com coragem.', '[]'::jsonb, 'active', 'Santa Sé', 'https://www.vatican.va/content/john-paul-ii/pt/biografia/documents/hf_jp-ii_spe_20190722_biografia.html', 'https://www.vatican.va/content/john-paul-ii/pt/biografia/documents/hf_jp-ii_spe_20190722_biografia.html', '{"century":20,"sources":[{"url":"https://www.vatican.va/content/john-paul-ii/pt/biografia/documents/hf_jp-ii_spe_20190722_biografia.html","year":"2019","title":"Perfil biográfico de João Paulo II","author":"Santa Sé"}],"biography_full":{"missao":"Conduzir a Igreja como sucessor de Pedro e anunciar Cristo em todos os continentes.","origem":"Wadowice, Polônia","chamado":"Sacerdote; bispo; Papa","heranca":"Seu magistério e testemunho pastoral continuam a influenciar a Igreja contemporânea.","testemunho":"João Paulo II convidou repetidamente a abrir as portas a Cristo e a viver a esperança com coragem."},"content_status":"partial","historical_context":"Polônia do século XX, Segunda Guerra Mundial, comunismo e renovação pós-conciliar.","spiritual_practice":{"prayer":"São João Paulo II, rogai por nós.","purpose":"João Paulo II convidou repetidamente a abrir as portas a Cristo e a viver a esperança com coragem.","live_today":"Traduzir a virtude cristã em um gesto concreto no cotidiano."}}'::jsonb),
('sao-jose', 'São José', 'Esposo da Virgem Maria e Padroeiro da Igreja Universal', '19 de março', 3, 19, 'Século I a.C. (data desconhecida)', 'Século I (data desconhecida)', 'confessor', 'Terra de Israel', 'Esposo de Maria; pai legal de Jesus; trabalhador', null, 'Nazaré', 'Esposo da Virgem Maria e pai legal de Jesus, São José é apresentado pelos Evangelhos como homem justo. Sua presença discreta e fiel está a serviço do plano de Deus.', 'A tradição cristã contempla José como esposo de Maria e guardião de Jesus. A carta apostólica Patris corde, do Papa Francisco, recorda sua paternidade na ternura, na obediência, no acolhimento e no trabalho. Os Evangelhos não informam datas de nascimento ou morte; por isso, o catálogo não atribui datas exatas.', 'Guardar e servir Jesus e Maria com fidelidade cotidiana.', 'Padroeiro da Igreja Universal; modelo de paternidade responsável e trabalho digno.', 'A espiritualidade de São José ensina a escutar, discernir e agir com confiança, sem buscar protagonismo.', '[]'::jsonb, 'active', 'Santa Sé', 'https://www.vatican.va/content/francesco/pt/apost_letters/documents/papa-francesco-lettera-ap_20201208_patris-corde.html', 'https://www.vatican.va/content/francesco/pt/apost_letters/documents/papa-francesco-lettera-ap_20201208_patris-corde.html', '{"century":1,"sources":[{"url":"https://www.vatican.va/content/francesco/pt/apost_letters/documents/papa-francesco-lettera-ap_20201208_patris-corde.html","year":"2020","title":"Patris corde","author":"Papa Francisco — Santa Sé"}],"biography_full":{"missao":"Guardar e servir Jesus e Maria com fidelidade cotidiana.","origem":"Nazaré","chamado":"Esposo de Maria; pai legal de Jesus; trabalhador","heranca":"Padroeiro da Igreja Universal; modelo de paternidade responsável e trabalho digno.","testemunho":"A espiritualidade de São José ensina a escutar, discernir e agir com confiança, sem buscar protagonismo."},"content_status":"partial","historical_context":"Judeia e Galileia no contexto do nascimento de Jesus.","spiritual_practice":{"prayer":"São José, rogai por nós.","purpose":"A espiritualidade de São José ensina a escutar, discernir e agir com confiança, sem buscar protagonismo.","live_today":"Traduzir a virtude cristã em um gesto concreto no cotidiano."}}'::jsonb),
('sao-tomas-de-aquino', 'São Tomás de Aquino', 'Doutor Angélico', '28 de janeiro', 1, 28, '1224 ou 1225', '7 de março de 1274', 'doctor', 'Itália', 'Frade dominicano; teólogo; Doutor da Igreja', null, 'Roccasecca, Itália', 'Dominicano e Doutor da Igreja, Tomás de Aquino é reconhecido pela integração entre fé e razão e pelo serviço à teologia. A Santa Sé o apresenta como mestre de pensamento e modelo de vida teológica.', 'Tomás nasceu em Roccasecca, na Itália, e ingressou na Ordem dos Pregadores. Tornou-se professor e autor de obras fundamentais, entre elas a Suma Teológica. Sua inteligência esteve a serviço da compreensão da fé e da busca da verdade, sem separar estudo, oração e vida virtuosa.', 'Servir à Igreja por meio do ensino, da pregação e da síntese teológica.', 'Sua obra tornou-se referência duradoura para a teologia católica.', 'Tomás ensina a buscar a verdade com rigor intelectual, humildade e abertura à fé.', '[]'::jsonb, 'active', 'Santa Sé', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2010/documents/hf_ben-xvi_aud_20100602.html', 'https://www.vatican.va/content/benedict-xvi/pt/audiences/2010/documents/hf_ben-xvi_aud_20100602.html', '{"century":13,"sources":[{"url":"https://www.vatican.va/content/benedict-xvi/pt/audiences/2010/documents/hf_ben-xvi_aud_20100602.html","year":"2010","title":"Audiência geral — São Tomás de Aquino","author":"Bento XVI — Santa Sé"}],"biography_full":{"missao":"Servir à Igreja por meio do ensino, da pregação e da síntese teológica.","origem":"Roccasecca, Itália","chamado":"Frade dominicano; teólogo; Doutor da Igreja","heranca":"Sua obra tornou-se referência duradoura para a teologia católica.","testemunho":"Tomás ensina a buscar a verdade com rigor intelectual, humildade e abertura à fé."},"content_status":"partial","historical_context":"Universidades medievais e renovação intelectual do século XIII.","spiritual_practice":{"prayer":"São Tomás de Aquino, rogai por nós.","purpose":"Tomás ensina a buscar a verdade com rigor intelectual, humildade e abertura à fé.","live_today":"Traduzir a virtude cristã em um gesto concreto no cotidiano."}}'::jsonb)
